import '../../domain/entities/explore_category.dart';
import '../../domain/entities/explore_metadata.dart';
import '../models/explore_content_model.dart';

List<ExploreContentModel> getTurkiyeLaunchCatalog(String languageCode) {
  final tr = languageCode.trim().toLowerCase() == 'tr';
  return _items.map((item) => item.toModel(tr)).toList(growable: false);
}

class _TurkiyeLaunchItem {
  const _TurkiyeLaunchItem({required this.id, required this.cityEn, required this.cityTr, required this.category, required this.titleEn, required this.titleTr, required this.latitude, required this.longitude, required this.coverImageUrl});
  final String id, cityEn, cityTr, titleEn, titleTr, coverImageUrl;
  final ExploreCategory category;
  final double latitude, longitude;

  ExploreContentModel toModel(bool tr) {
    final city = tr ? cityTr : cityEn;
    final title = tr ? titleTr : titleEn;
    final copy = _copy(category, tr);
    return ExploreContentModel(
      id: id, countryCode: 'TR', countryName: 'Türkiye', cityName: city,
      category: category, title: title,
      shortDescription: copy.$1.replaceAll('{city}', city),
      description: copy.$2.replaceAll('{city}', city),
      latitude: latitude, longitude: longitude, coverImageUrl: coverImageUrl,
      tags: <String>[category.value, cityEn.toLowerCase(), cityTr.toLowerCase(), 'turkiye', 'turkey'],
      metadata: _metadata(category), galleryImageUrls: const [],
      isFeatured: category == ExploreCategory.place || category == ExploreCategory.food,
    );
  }
}

(String, String) _copy(ExploreCategory category, bool tr) {
  final key = category.value;
  final map = tr ? _copyTr : _copyEn;
  return map[key] ?? map['place']!;
}

ExploreMetadata _metadata(ExploreCategory category) => ExploreMetadata(
  priceLevel: switch (category) { ExploreCategory.place || ExploreCategory.culture => null, _ => 2 },
  bestTime: switch (category) { ExploreCategory.place => 'Morning or late afternoon', ExploreCategory.culture => 'Late afternoon or evening', _ => 'Local meal or market time' },
  estimatedVisitMinutes: switch (category) { ExploreCategory.place => 90, ExploreCategory.culture => 60, _ => null },
  localTip: 'Map pin is approximate until editorial verification is complete.',
  coordinatePrecision: 'city_area',
  editorialStatus: 'needs_exact_pin_review',
);

